'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const N = Number(input[0]);
const Q = Number(input[1]);
let grid = input.slice(2, 2 + N).map(row => row.split('').map(Number));

for (let step = 0; step < Q; step++) {
  const next = Array.from({ length: N }, () => Array(N).fill(0));

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      let neighbors = 0;

      for (let di = -1; di <= 1; di++) {
        for (let dj = -1; dj <= 1; dj++) {
          if (di === 0 && dj === 0) continue;

          const ni = i + di;
          const nj = j + dj;
          if (ni >= 0 && ni < N && nj >= 0 && nj < N) {
            neighbors += grid[ni][nj];
          }
        }
      }

      if (neighbors === 3 || (grid[i][j] === 1 && neighbors === 2)) {
        next[i][j] = 1;
      }
    }
  }

  grid = next;
}

console.log(grid.map(row => row.join('')).join('\n'));
